ALTER TABLE public."Feature04_Technical_Indicator"
 ADD COLUMN smi double precision,
 ADD CONSTRAINT feature04_smi_valid CHECK(smi IS NULL OR (smi>'-Infinity'::double precision AND smi<'Infinity'::double precision)),
